// Generated by pnpm worker:build-context -- always runs before tsup in worker:build

import { createGeminiChat } from "@tanstack/ai-gemini";
import { type Env, stringVars } from "./brains.js";
import { createBrainsHandler } from "./brains-payload.js";
import { createChatHandler } from "./chat-handler.js";
import { getCorsHeaders } from "./cors.js";
import { CHUNKS, SEARCH_INDEX_JSON, VOCABULARY } from "./docs-context.js";
import { handleLegacyRequest } from "./legacy-handler.js";
import { nowMs } from "./rate-limit.js";

type RouteHandler = (
  request: Request,
  env: Env,
  cors: Record<string, string>,
) => Promise<Response>;

export interface Routes {
  /** `POST /` — the frozen protocol the live site's current client speaks (D3). */
  legacy: RouteHandler;
  /** `POST /api/chat` — the new protocol. */
  chat: RouteHandler;
  /** `GET /api/brains` — what the badge and the brain menu show (plan #309 D10). */
  brains: RouteHandler;
}

function errorResponse(
  status: number,
  error: string,
  cors: Record<string, string>,
): Response {
  return new Response(JSON.stringify({ error, retryable: false }), {
    status,
    headers: { "Content-Type": "application/json", ...cors },
  });
}

export function createWorker(routes: Routes) {
  return {
    async fetch(request: Request, env: Env): Promise<Response> {
      const cors = getCorsHeaders(request.headers.get("origin"));

      if (request.method === "OPTIONS") {
        return new Response(null, { status: 204, headers: cors });
      }

      const { pathname } = new URL(request.url);
      const target =
        pathname === "/"
          ? { handle: routes.legacy, method: "POST" }
          : pathname === "/api/chat"
            ? { handle: routes.chat, method: "POST" }
            : pathname === "/api/brains"
              ? { handle: routes.brains, method: "GET" }
              : null;
      if (target === null) return errorResponse(404, "Not found.", cors);
      if (request.method !== target.method) {
        return errorResponse(405, "Method not allowed.", {
          ...cors,
          Allow: `${target.method}, OPTIONS`,
        });
      }
      return target.handle(request, env, cors);
    },
  };
}

export default createWorker({
  // The frozen route reads string variables only (key, rate limits), so it is handed those and nothing else.
  legacy: (request, env, cors) =>
    handleLegacyRequest(request, stringVars(env), cors),
  chat: createChatHandler({
    // Every Gemini brain's id is a model id of the adapter; the registry, not the adapter's own list, decides which.
    createAdapter: (model, apiKey) =>
      createGeminiChat(model as Parameters<typeof createGeminiChat>[0], apiKey),
    corpus: {
      chunks: CHUNKS,
      searchIndexJson: SEARCH_INDEX_JSON,
      vocabulary: VOCABULARY,
    },
    now: nowMs,
  }),
  brains: createBrainsHandler({ now: nowMs }),
});
